1	import React, { useEffect, useState } from 'react';
2	
3	// The detail of a single invoice, shown when an invoice is opened from the project's invoice list.
4	// Owns its own state (CLAUDE.md — features own their state). Lists the invoice's line items — the
5	// things being charged for (description, quantity, unit price) — a derived total (the sum of each
6	// line's qty * unit price), and a form to add another line. Amounts render with 2 decimals.
7	type LineItem = {
8	  id: number;
9	  invoiceId: number;
10	  description: string;
11	  qty: number;
12	  unitPrice: number;
13	};
14	
15	function money(n: number): string {
16	  return Number(n).toLocaleString('en-US', { style: 'currency', currency: 'USD' });
17	}
18	
19	type EditDraft = { description: string; qty: string; unitPrice: string };
20	
21	// A payment a client has made against this invoice: how much (amount) and when (date, yyyy-MM-dd).
22	type Payment = {
23	  id: number;
24	  invoiceId: number;
25	  amount: number;
26	  date: string;
27	};
28	
29	export function InvoiceDetail({ invoiceId }: { invoiceId: number }) {
30	  const [lineItems, setLineItems] = useState<LineItem[]>([]);
31	  const [description, setDescription] = useState('');
32	  const [qty, setQty] = useState('');
33	  const [unitPrice, setUnitPrice] = useState('');
34	  const [editingId, setEditingId] = useState<number | null>(null);
35	  const [draft, setDraft] = useState<EditDraft>({ description: '', qty: '', unitPrice: '' });
36	  const [payments, setPayments] = useState<Payment[]>([]);
37	  const [paymentAmount, setPaymentAmount] = useState('');
38	  const [paymentDate, setPaymentDate] = useState('');
39	  const [status, setStatus] = useState('');
40	
41	  async function load() {
42	    const res = await fetch(`/api/lineitems?invoiceId=${invoiceId}`);
43	    if (res.ok) {
44	      setLineItems(await res.json());
45	    }
46	  }
47	
48	  async function loadPayments() {
49	    const res = await fetch(`/api/payments?invoiceId=${invoiceId}`);
50	    if (res.ok) {
51	      setPayments(await res.json());
52	    }
53	  }
54	
55	  // The invoice's status is worked out server-side from the payments recorded against it, so we
56	  // re-read it whenever the payments change rather than tracking it by hand.
57	  async function loadStatus() {
58	    const res = await fetch(`/api/invoices/get?id=${invoiceId}`);
59	    if (res.ok) {
60	      const inv: { status: string } = await res.json();
61	      setStatus(inv.status);
62	    }
63	  }
64	
65	  useEffect(() => {
66	    void load();
67	    void loadPayments();
68	    void loadStatus();
69	  }, [invoiceId]);
70	
71	  async function onRecordPayment(e: React.FormEvent) {
72	    e.preventDefault();
73	    const res = await fetch('/api/payments', {
74	      method: 'POST',
75	      headers: { 'Content-Type': 'application/json' },
76	      body: JSON.stringify({
77	        invoiceId,
78	        amount: Number(paymentAmount),
79	        date: paymentDate,
80	      }),
81	    });
82	    if (res.ok) {
83	      const created: Payment = await res.json();
84	      setPayments((prev) => [...prev, created]);
85	      setPaymentAmount('');
86	      setPaymentDate('');
87	      void loadStatus();
88	    }
89	  }
90	
91	  async function onSubmit(e: React.FormEvent) {
92	    e.preventDefault();
93	    const res = await fetch('/api/lineitems', {
94	      method: 'POST',
95	      headers: { 'Content-Type': 'application/json' },
96	      body: JSON.stringify({
97	        invoiceId,
98	        description,
99	        qty: Number(qty),
100	        unitPrice: Number(unitPrice),
101	      }),
102	    });
103	    if (res.ok) {
104	      const created: LineItem = await res.json();
105	      setLineItems((prev) => [...prev, created]);
106	      setDescription('');
107	      setQty('');
108	      setUnitPrice('');
109	    }
110	  }
111	
112	  async function onRemove(id: number) {
113	    const res = await fetch('/api/lineitems/remove', {
114	      method: 'POST',
115	      headers: { 'Content-Type': 'application/json' },
116	      body: JSON.stringify({ id }),
117	    });
118	    if (res.ok) {
119	      setLineItems((prev) => prev.filter((li) => li.id !== id));
120	      if (editingId === id) {
121	        setEditingId(null);
122	      }
123	    }
124	  }
125	
126	  function startEdit(li: LineItem) {
127	    setEditingId(li.id);
128	    setDraft({
129	      description: li.description,
130	      qty: String(li.qty),
131	      unitPrice: String(li.unitPrice),
132	    });
133	  }
134	
135	  async function onSaveEdit(id: number) {
136	    const res = await fetch('/api/lineitems/update', {
137	      method: 'POST',
138	      headers: { 'Content-Type': 'application/json' },
139	      body: JSON.stringify({
140	        id,
141	        description: draft.description,
142	        qty: Number(draft.qty),
143	        unitPrice: Number(draft.unitPrice),
144	      }),
145	    });
146	    if (res.ok) {
147	      const updated: LineItem = await res.json();
148	      setLineItems((prev) => prev.map((li) => (li.id === id ? updated : li)));
149	      setEditingId(null);
150	    }
151	  }
152	
153	  const total = lineItems.reduce((sum, li) => sum + li.qty * Number(li.unitPrice), 0);
154	
155	  return (
156	    <section data-testid="invoice-detail">
157	      <p>
158	        Status: <span data-testid="invoice-status">{status}</span>
159	      </p>
160	      <h3>Line items</h3>
161	      <form data-testid="lineitem-form" onSubmit={onSubmit}>
162	        <input
163	          data-testid="lineitem-form-description"
164	          placeholder="Description"
165	          value={description}
166	          onChange={(e) => setDescription(e.target.value)}
167	        />
168	        <input
169	          data-testid="lineitem-form-qty"
170	          placeholder="Qty"
171	          value={qty}
172	          onChange={(e) => setQty(e.target.value)}
173	        />
174	        <input
175	          data-testid="lineitem-form-unitprice"
176	          placeholder="Unit price"
177	          value={unitPrice}
178	          onChange={(e) => setUnitPrice(e.target.value)}
179	        />
180	        <button type="submit" data-testid="lineitem-form-submit">
181	          Add line item
182	        </button>
183	      </form>
184	
185	      <table data-testid="invoice-lineitems-table">
186	        <thead>
187	          <tr>
188	            <th>Description</th>
189	            <th>Qty</th>
190	            <th>Unit price</th>
191	            <th>Amount</th>
192	            <th>Actions</th>
193	          </tr>
194	        </thead>
195	        <tbody>
196	          {lineItems.map((li) =>
197	            editingId === li.id ? (
198	              <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
199	                <td>
200	                  <input
201	                    data-testid={`lineitem-edit-description-${li.id}`}
202	                    value={draft.description}
203	                    onChange={(e) => setDraft((d) => ({ ...d, description: e.target.value }))}
204	                  />
205	                </td>
206	                <td>
207	                  <input
208	                    data-testid={`lineitem-edit-qty-${li.id}`}
209	                    value={draft.qty}
210	                    onChange={(e) => setDraft((d) => ({ ...d, qty: e.target.value }))}
211	                  />
212	                </td>
213	                <td>
214	                  <input
215	                    data-testid={`lineitem-edit-unitprice-${li.id}`}
216	                    value={draft.unitPrice}
217	                    onChange={(e) => setDraft((d) => ({ ...d, unitPrice: e.target.value }))}
218	                  />
219	                </td>
220	                <td data-testid="lineitem-amount">
221	                  {money(Number(draft.qty) * Number(draft.unitPrice))}
222	                </td>
223	                <td>
224	                  <button
225	                    type="button"
226	                    data-testid={`lineitem-save-${li.id}`}
227	                    onClick={() => void onSaveEdit(li.id)}
228	                  >
229	                    Save
230	                  </button>
231	                  <button
232	                    type="button"
233	                    data-testid={`lineitem-cancel-${li.id}`}
234	                    onClick={() => setEditingId(null)}
235	                  >
236	                    Cancel
237	                  </button>
238	                </td>
239	              </tr>
240	            ) : (
241	              <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
242	                <td data-testid="lineitem-description">{li.description}</td>
243	                <td data-testid="lineitem-qty">{li.qty}</td>
244	                <td data-testid="lineitem-unitprice">{money(li.unitPrice)}</td>
245	                <td data-testid="lineitem-amount">{money(li.qty * Number(li.unitPrice))}</td>
246	                <td>
247	                  <button
248	                    type="button"
249	                    data-testid={`lineitem-edit-${li.id}`}
250	                    onClick={() => startEdit(li)}
251	                  >
252	                    Edit
253	                  </button>
254	                  <button
255	                    type="button"
256	                    data-testid={`lineitem-remove-${li.id}`}
257	                    onClick={() => void onRemove(li.id)}
258	                  >
259	                    Remove
260	                  </button>
261	                </td>
262	              </tr>
263	            ),
264	          )}
265	        </tbody>
266	      </table>
267	
268	      <p>
269	        Total: <span data-testid="invoice-amount">{money(total)}</span>
270	      </p>
271	
272	      <h3>Payments</h3>
273	      <form data-testid="payment-form" onSubmit={onRecordPayment}>
274	        <input
275	          data-testid="payment-form-amount"
276	          placeholder="Amount"
277	          value={paymentAmount}
278	          onChange={(e) => setPaymentAmount(e.target.value)}
279	        />
280	        <input
281	          data-testid="payment-form-date"
282	          placeholder="Date"
283	          value={paymentDate}
