204	    /** The list of fixture rows under {@code key}, or empty when the spec omitted that table. */
205	    @SuppressWarnings("unchecked")
206	    private static List<Map<String, Object>> rows(Map<String, Object> fixture, String key) {
207	        return (List<Map<String, Object>>) fixture.getOrDefault(key, List.of());
208	    }
