216	     * Seeding explicit ids into an IDENTITY column does not advance H2's generator, so a later
217	     * app-side INSERT would reuse a seeded id and hit the PK. Bump the generator past the seeded
218	     * rows. Use for any table seeded with explicit ids that is also written to app-side.
219	     */
220	    private void bumpIdentity(String table) {
221	        Long next = jdbc.queryForObject(
222	                "SELECT COALESCE(MAX(id), 0) + 1 FROM " + table, Long.class);
223	        jdbc.execute("ALTER TABLE " + table + " ALTER COLUMN id RESTART WITH " + next);
224	    }
225	}
