            jdbc.update(
                    "INSERT INTO notes (id, target_type, target_id, body, created_at)"
                            + " VALUES (?, ?, ?, ?, ?)",
                    id(n, "id"), n.get("targetType"), id(n, "targetId"), n.get("text"),
