                        + " VALUES (?, ?, ?, ?)",
                new String[] {"id"});
        ps.setLong(1, invoiceId);
        ps.setString(2, description);
        ps.setInt(3, qty);
        ps.setBigDecimal(4, unitPrice);
        return ps;
    }, keys);
    return new LineItem(keys.getKey().longValue(), invoiceId, description, qty, unitPrice);
