                  />
                </td>
                <td data-testid="lineitem-amount">
                  {money(Number(draft.qty) * Number(draft.unitPrice))}
                </td>
                <td>
                  <button
                    type="button"
                    data-testid={`lineitem-save-${li.id}`}
                    onClick={() => void onSaveEdit(li.id)}
                  >
                    Save
                  </button>
                  <button
                    type="button"
                    data-testid={`lineitem-cancel-${li.id}`}
